function head(eyebrow,title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
function notice(text,kind=''){return `<div class="notice ${kind}">${icon('info')}<p>${text}</p></div>`;}
function stat(label,value,unit,ic,foot){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="stat-value mono">${value}<span>${unit}</span></div><div class="stat-foot">${foot}</div></div>`;}
function chart(group){const rows=historicalRuns.filter(r=>r.types===group);const height=rows.length*49+56;const barX=185;const width=360;return `<svg viewBox="0 0 635 ${height}" role="img" aria-label="${group}종 공격 실험의 모델별 공격 성공률">${[0,25,50,75,100].map(t=>`<line x1="${barX+width*t/100}" y1="10" x2="${barX+width*t/100}" y2="${height-30}" stroke="#eaf0f7" stroke-dasharray="3 4"/><text x="${barX+width*t/100}" y="${height-8}" text-anchor="middle" fill="#9ba8b9" font-size="10">${t}%</text>`).join('')}${rows.map((r,i)=>{const y=18+i*49;const color=r.model.includes('deepseek')?'#8c80d7':'#4572eb';return `<text x="0" y="${y+19}" fill="#71839d" font-size="11">${esc(shortModel(r.model))}</text><rect x="${barX}" y="${y}" width="${width}" height="27" rx="4" fill="#f5f7fc"/><rect x="${barX}" y="${y}" width="${width*r.asr/100}" height="27" rx="4" fill="${color}"/><text x="${barX+width*r.asr/100+9}" y="${y+18}" fill="#4c6183" font-weight="600" font-size="11">${r.asr.toFixed(2)}%</text>`;}).join('')}</svg>`;}
function historyTable(rows){return `<div class="table-wrap"><table><thead><tr><th>모델</th><th>공격 구성</th><th>시도 / 성공</th><th>공격 성공률</th><th>기록일</th><th>데이터 상태</th><th><span class="screen-reader">상세</span></th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="model-name"><span class="model-mark ${r.model.includes('deepseek')?'deep':''}">${r.model.includes('deepseek')?'D':'✦'}</span>${esc(r.model)}</div></td><td>${r.types===3?'기본 3종':'확장 5종'}</td><td class="mono">${r.attempts} / ${r.successes}</td><td class="asr mono">${r.asr.toFixed(2)}%</td><td class="mono">2026.09.30</td><td>${tag(r.id==='hist-deepseek-extended'?'재검토 의견 있음':'기존 실험 기록',r.id==='hist-deepseek-extended'?'amber':'blue')}</td><td><button class="icon-button" data-action="history-detail" data-id="${r.id}" aria-label="${esc(r.model)} ${r.types}종 실험 상세">${icon('chevron')}</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty-table">조건에 맞는 실험 기록이 없어요.</td></tr>'}</tbody></table></div>`;}
